package br.com.casanotify.tv;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import android.provider.Settings;import org.json.JSONObject;
public final class NotifyService extends Service{
 public static volatile boolean running;public static volatile String lastError="";private Prefs prefs;private LanServer server,secureServer;private OverlayManager overlay;private DiscoveryAdvertiser discovery;
 public void onCreate(){super.onCreate();prefs=new Prefs(this);NotificationManager manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("receiver","Recebimento de avisos",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,1,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE),stop=PendingIntent.getService(this,2,new Intent(this,NotifyService.class).setAction("STOP"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,"receiver").setSmallIcon(R.drawable.ic_notification).setContentTitle("CasaNotify TV ativo").setContentText("Aguardando avisos locais do Home Assistant").setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(null,"Parar",stop).build()).build();if(Build.VERSION.SDK_INT>=34)startForeground(1,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(1,n);if(!Ui.accepted(this)||!prefs.enabled()||!Settings.canDrawOverlays(this)){stopSelf();return;}try{overlay=new OverlayManager(this,prefs);ApiController api=new ApiController(this,prefs,overlay);secureServer=new LanServer(Prefs.SECURE_PORT,api,LocalTls.server());server=new LanServer(Prefs.PORT,api);secureServer.start();server.start();running=true;lastError="";discovery=new DiscoveryAdvertiser(this,prefs);discovery.start();}catch(Exception e){lastError="Não foi possível iniciar o receptor seguro. Confira se as portas 8765/8766 estão livres e a data/hora da TV estão corretas.";prefs.enabled(false);stopSelf();}}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){prefs.enabled(false);stopSelf();return START_NOT_STICKY;}if(i!=null&&"TEST".equals(i.getAction())&&overlay!=null)try{overlay.receive(new Notice(new JSONObject().put("title","Tudo conectado!").put("message","Os avisos da sua casa aparecem aqui.").put("icon","check").put("replace",true),prefs.defaults()));}catch(Exception ignored){}return prefs.enabled()?START_STICKY:START_NOT_STICKY;}
 public IBinder onBind(Intent i){return null;}public void onDestroy(){running=false;if(discovery!=null)discovery.close();if(server!=null)server.close();if(secureServer!=null)secureServer.close();if(overlay!=null)overlay.destroy();super.onDestroy();}
}
